-- +goose Up
-- organizations is the root of the tenant hierarchy: projects and everything
-- below them belong to exactly one organization. IDs are UUIDv7 values
-- generated by the application.
CREATE TABLE organizations (
    id         uuid        PRIMARY KEY,
    name       text        NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- +goose Down
DROP TABLE organizations;
